"""Find the longest palindrome in a given string."""

# Initialize variables to keep track of the longest palindrome found so far
longest_palindrome = ""
current_palindrome = ""

for i in range(len(s)):
for j in range(i+1, len(s)):
if s[i] == s[j]:
current_palindrome += s[j]
elif current_palindrome!= "":

