Write a Python program to find the sum of the first 1000 prime numbers

# Find the sum of the first 1000 prime numbers
sum = 0
for i in range(1000):
    if i > 1:
        for j in range(2, i):
            if i % j == 0:
                break
        else:
            sum += i
print("The sum of the first 1000 prime numbers is:", sum)corlib

